# Install drivers from drivers\platforms based on motherboard model.
# Works for USB-stick install AND PXE install.
function Find-InstallRoot {
    foreach ($drive in [System.IO.DriveInfo]::GetDrives()) {
        $root = $drive.RootDirectory.FullName
        if (Test-Path (Join-Path $root "drivers\platforms")) { return $root }
    }
    return $null
}
$driveRoot = Find-InstallRoot
if (-not $driveRoot) {
    Write-Host "USB install root not found. Attempting PXE mount..."
    $netReady = $false
    for ($i = 1; $i -le 60; $i++) {
        if (Test-Connection 10.0.6.42 -Count 1 -Quiet -ErrorAction SilentlyContinue) { $netReady = $true; break }
        Start-Sleep -Seconds 2
    }
    if ($netReady) {
        Write-Host "Server reachable. Mounting \\10.0.6.42\winpxe\common as F:"
        & net use F: \\10.0.6.42\winpxe\common /user:pxe pxe /persistent:no 2>&1 | Out-String | Write-Host
        if (Test-Path "F:\drivers\platforms") { $driveRoot = "F:\"; Write-Host "PXE share mounted as F:" }
    }
}
if (-not $driveRoot) { Write-Warning "drivers\platforms not found. Skipping."; exit }
Write-Host "Using install root: $driveRoot"
$product = (Get-WmiObject Win32_BaseBoard).Product
Write-Host "Detected platform: $product"
$folderName = $product -replace '\s+', '_'
$driverPath = Join-Path $driveRoot "drivers\platforms\$folderName"
$commonPath = Join-Path $driveRoot "drivers\common\drivers"
if (Test-Path $commonPath) {
    Write-Host "Installing COMMON drivers..."
    Get-ChildItem $commonPath -Recurse -Filter *.inf | ForEach-Object { & pnputil /add-driver $_.FullName /install }
}
if (Test-Path $driverPath) {
    Write-Host "Installing PLATFORM drivers..."
    Get-ChildItem $driverPath -Recurse -Filter *.inf | ForEach-Object { & pnputil /add-driver $_.FullName /install }
}
& pnputil /scan-devices

# === PXE: copy SMB payload to local C:\IPDROM, then run customization from local ===
# Rationale: original pipeline assumes F:\ is always present (USB stick).
# With PXE, F:\ is a network mount that dies on reboot and has race conditions.
# Solution: at FirstLogon, copy the entire share to C:\IPDROM\ once, then run
# everything from local copy. Pipeline + launcher use C:\IPDROM\ from then on.
#
# Also creates `subst F: C:\IPDROM` and writes a run-key to recreate it on every
# logon, so any script that still hardcodes F:\ keeps working.

$LocalRoot = 'C:\IPDROM'
$LogFile   = 'C:\ProgramData\IPDROM\Logs\unattend-02.log'
New-Item -ItemType Directory -Path (Split-Path $LogFile) -Force -ErrorAction SilentlyContinue | Out-Null

function W { param([string]$m) "[{0}] {1}" -f (Get-Date -f 'yyyy-MM-dd HH:mm:ss'),$m | Tee-Object -Append -FilePath $LogFile | Out-Host }

function Find-CustomizationScript {
    foreach ($drive in [System.IO.DriveInfo]::GetDrives()) {
        $root = $drive.RootDirectory.FullName
        $testPath = Join-Path $root "customization\scripts\setup_apps_and_theme.ps1"
        if (Test-Path $testPath) { return @{ Root = $root; Path = $testPath } }
    }
    return $null
}

function Mount-PxeIfNeeded {
    if (Find-CustomizationScript) { return }
    W "USB customization not found. Attempting PXE SMB mount..."
    for ($i = 1; $i -le 60; $i++) {
        if (Test-Connection 10.0.6.42 -Count 1 -Quiet -ErrorAction SilentlyContinue) { break }
        Start-Sleep -Seconds 2
    }
    # If F: is currently taken by a USB volume (typically IPDROM auto-mounted
    # after WinPE format), move it to a high letter so F: is free for SMB mount.
    try {
        $part = Get-Partition -DriveLetter F -ErrorAction SilentlyContinue
        if ($part) {
            $disk = Get-Disk -Number $part.DiskNumber -ErrorAction SilentlyContinue
            if ($disk -and $disk.BusType -eq 'USB') {
                foreach ($newLtr in 'XWQPONMKJIH'.ToCharArray()) {
                    if (-not (Get-Volume -DriveLetter $newLtr -ErrorAction SilentlyContinue)) {
                        Set-Partition -DiskNumber $part.DiskNumber -PartitionNumber $part.PartitionNumber -NewDriveLetter $newLtr -ErrorAction SilentlyContinue
                        W "Moved USB volume from F: to ${newLtr}: to free F: for SMB mount."
                        break
                    }
                }
            }
        }
    } catch { W "Failed to check/move F: - $($_.Exception.Message)" }
    & net use F: \\10.0.6.42\winpxe\common /user:pxe pxe /persistent:no 2>&1 | Out-String | ForEach-Object { W $_ }
}

function Copy-PayloadLocal {
    param([string]$Source)
    if (Test-Path "$LocalRoot\customization\scripts\setup_apps_and_theme.ps1") {
        W "$LocalRoot already populated, skipping copy."
        return $LocalRoot
    }
    W "Copying $Source -> $LocalRoot (this takes 5-15 minutes on 2.5G LAN)..."
    New-Item -ItemType Directory -Path $LocalRoot -Force -ErrorAction SilentlyContinue | Out-Null
    $rcLog = 'C:\ProgramData\IPDROM\Logs\robocopy_payload.log'
    & robocopy.exe $Source $LocalRoot /E /XJ /R:2 /W:5 /MT:8 /NFL /NDL /NP /LOG:$rcLog | Out-Null
    $rcExit = $LASTEXITCODE
    W "robocopy completed (exit=$rcExit)."
    # Do NOT bail on exit 8-15 alone: transient SMB glitches during a 100+ GB
    # copy regularly bump the exit code even when robocopy's retries pulled
    # everything through. Verify essentials — if they exist, payload is usable.
    $essentials = @(
        'customization\scripts\setup_apps_and_theme.ps1',
        'customization\scripts\launch_auto_stress_after_reboot.ps1',
        'customization\scripts\register_auto_stress_after_reboot.ps1',
        'customization\scripts\auto_stress_test.ps1',
        'software',
        'SoftForTest'
    )
    foreach ($rel in $essentials) {
        if (-not (Test-Path -LiteralPath (Join-Path $LocalRoot $rel))) {
            W "FATAL: essential missing after copy: $rel (robocopy exit=$rcExit). See $rcLog"
            return $null
        }
    }
    if ($rcExit -ge 16) {
        W "FATAL: robocopy fatal error (exit=$rcExit). See $rcLog"
        return $null
    }
    if ($rcExit -ge 8) {
        W "WARN: robocopy reported partial failures (exit=$rcExit) but all essentials present. Continuing."
    }
    return $LocalRoot
}

function Ensure-SubstF {
    param([string]$Target)
    # subst is per-session; create it now AND register a logon-time recreator.
    & subst F: /D 2>$null | Out-Null
    & subst F: $Target 2>&1 | ForEach-Object { W $_ }
    # Recreate on every logon via Run key (per-user but IPDROM auto-logs in)
    $runKey = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run'
    Set-ItemProperty -Path $runKey -Name 'IPDROM_SubstF' -Value ('cmd.exe /c subst F: "{0}"' -f $Target) -Type String
    W "subst F: -> $Target (plus Run-key for reboots)."
}

# === Anti-idle: prevent lockscreen / sleep / NIC-power-down during payload copy ===
# Robocopy 100+ GB over SMB is a 15-min operation. If Windows idle-locks the session
# mid-copy (default: monitor 5 min, unattended-sleep 2 min), NIC drops to low-power,
# SMB sessions time out, robocopy retries stretch it to hours. Flatten power policy
# and pin the current thread as SYSTEM+DISPLAY-required so nothing goes to sleep.
try {
    powercfg.exe /change monitor-timeout-ac 0    | Out-Null
    powercfg.exe /change monitor-timeout-dc 0    | Out-Null
    powercfg.exe /change standby-timeout-ac 0    | Out-Null
    powercfg.exe /change standby-timeout-dc 0    | Out-Null
    powercfg.exe /change disk-timeout-ac 0       | Out-Null
    powercfg.exe /change disk-timeout-dc 0       | Out-Null
    powercfg.exe /change hibernate-timeout-ac 0  | Out-Null
    powercfg.exe /change hibernate-timeout-dc 0  | Out-Null
    # System unattended sleep timeout (default 2 min) — hidden by default, unmask then clear.
    powercfg.exe -attributes SUB_SLEEP 7bc4a2f9-d8fc-4469-b07b-33eb785aaca0 -ATTRIB_HIDE | Out-Null
    powercfg.exe /SETACVALUEINDEX SCHEME_CURRENT SUB_SLEEP 7bc4a2f9-d8fc-4469-b07b-33eb785aaca0 0 | Out-Null
    powercfg.exe /SETDCVALUEINDEX SCHEME_CURRENT SUB_SLEEP 7bc4a2f9-d8fc-4469-b07b-33eb785aaca0 0 | Out-Null
    powercfg.exe /SETACTIVE SCHEME_CURRENT | Out-Null
    reg.exe add 'HKLM\SOFTWARE\Policies\Microsoft\Windows\Personalization' /v NoLockScreen /t REG_DWORD /d 1 /f | Out-Null
    $sig = '[DllImport("kernel32.dll")] public static extern uint SetThreadExecutionState(uint esFlags);'
    $es  = Add-Type -MemberDefinition $sig -Name PInvokeUA02 -Namespace Win32 -PassThru
    # 0x80000003 = ES_CONTINUOUS | ES_SYSTEM_REQUIRED | ES_DISPLAY_REQUIRED.
    # Written as a raw literal it overflows Int32 and PS can't cast the negative
    # result to UInt32. Parse as hex explicitly to skip the whole Int32 detour.
    [void]$es::SetThreadExecutionState([Convert]::ToUInt32('80000003', 16))
    W "Anti-idle armed (powercfg cleared + NoLockScreen + SetThreadExecutionState SYSTEM+DISPLAY)."
} catch {
    W "WARN: anti-idle setup partially failed: $($_.Exception.Message)"
}

Mount-PxeIfNeeded
$found = Find-CustomizationScript
if (-not $found) { W "FATAL: no customization script found anywhere."; exit 1 }

W "Found customization script on $($found.Root)."

# If source is a network drive, copy to local; otherwise use as-is.
$isNetwork = $false
try {
    $drv = Get-WmiObject Win32_LogicalDisk -Filter ("DeviceID='{0}'" -f $found.Root.TrimEnd('\')) -ErrorAction SilentlyContinue
    if ($drv -and $drv.DriveType -eq 4) { $isNetwork = $true }
} catch {}

if ($isNetwork) {
    W "Source $($found.Root) is a network drive. Will copy locally."
    $local = Copy-PayloadLocal -Source $found.Root
    if ($local) {
        Ensure-SubstF -Target $local
        # Switch found root to local copy
        $found.Root = "$local\"
        $found.Path = Join-Path $local 'customization\scripts\setup_apps_and_theme.ps1'
        # Save InstallRoot hint for launcher
        $stateDir = 'C:\ProgramData\IPDROM\State'
        New-Item -ItemType Directory -Path $stateDir -Force -ErrorAction SilentlyContinue | Out-Null
        Set-Content -Path (Join-Path $stateDir 'InstallRoot.txt') -Value $local -Encoding ascii
        W "InstallRoot.txt -> $local"
        # Unblock everything (legacy safety)
        Get-ChildItem -LiteralPath $local -Recurse -Force -ErrorAction SilentlyContinue | Unblock-File -ErrorAction SilentlyContinue
    } else {
        W "Local copy failed. Falling back to running directly from $($found.Root)."
    }
} else {
    W "Source $($found.Root) is a local drive (USB). Using as-is."
}

W "Running customization: $($found.Path)"
& $found.Path
W "Customization finished. unattend-02 done."

$scripts = @(
	{
		# === PXE: persist SL chosen at install time ===
		# Pattern match (not literal comparison) — sed substitutes both sides otherwise.
		$sl = "__INSTALL_SL__"
		if ($sl -match '^SL[A-Za-z0-9_-]+$') {
			if (-not (Test-Path 'HKLM:\Software\IPDROM')) {
				New-Item -Path 'HKLM:\Software\IPDROM' -Force | Out-Null
			}
			Set-ItemProperty -Path 'HKLM:\Software\IPDROM' -Name 'SL' -Value $sl -Type String
			Write-Host "Saved IPDROM SL: $sl"
		} else {
			Write-Host "No SL preselection (value '$sl' did not match ^SL pattern)."
		}
	};
	{
		# === Trust the PXE/SMB server: prevents SmartScreen and PS signing prompts ===
		$rangePath = 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Internet Settings\ZoneMap\Ranges\IPDROM_PXE'
		New-Item -Path $rangePath -Force | Out-Null
		Set-ItemProperty -Path $rangePath -Name ':Range' -Value '10.0.6.42'
		Set-ItemProperty -Path $rangePath -Name '*'      -Value 1 -Type DWord
		$policyZM = 'HKLM:\Software\Policies\Microsoft\Windows\CurrentVersion\Internet Settings'
		New-Item -Path $policyZM -Force | Out-Null
		Set-ItemProperty -Path $policyZM -Name 'Security_HKLM_only' -Value 1 -Type DWord
		$attachPath = 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\Attachments'
		New-Item -Path $attachPath -Force | Out-Null
		Set-ItemProperty -Path $attachPath -Name 'SaveZoneInformation'    -Value 1     -Type DWord
		Set-ItemProperty -Path $attachPath -Name 'DefaultFileTypeRisk'    -Value 0x6152 -Type DWord
		Set-ItemProperty -Path $attachPath -Name 'ScanWithAntiVirus'      -Value 1     -Type DWord
		Set-ItemProperty -Path $attachPath -Name 'HideZoneInfoOnProperties' -Value 1   -Type DWord
		Set-ExecutionPolicy -Scope 'LocalMachine' -ExecutionPolicy 'Bypass' -Force
		Write-Host "PXE server marked Intranet; SmartScreen suppressed."
	};
	{ reg.exe add "HKLM\SYSTEM\Setup\MoSetup" /v AllowUpgradesWithUnsupportedTPMOrCPU /t REG_DWORD /d 1 /f };
	{ reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\OOBE" /v BypassNRO /t REG_DWORD /d 1 /f };
	{ Remove-Item -LiteralPath 'Registry::HKLM\Software\Microsoft\WindowsUpdate\Orchestrator\UScheduler_Oobe\DevHomeUpdate' -Force -ErrorAction 'SilentlyContinue' };
	{ Remove-Item -LiteralPath 'C:\Users\Default\AppData\Roaming\Microsoft\Windows\Start Menu\Programs\OneDrive.lnk','C:\Windows\System32\OneDriveSetup.exe','C:\Windows\SysWOW64\OneDriveSetup.exe' -ErrorAction 'Continue' };
	{ Remove-Item -LiteralPath 'Registry::HKLM\Software\Microsoft\WindowsUpdate\Orchestrator\UScheduler_Oobe\OutlookUpdate' -Force -ErrorAction 'SilentlyContinue' };
	{ reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Communications" /v ConfigureChatAutoInstall /t REG_DWORD /d 0 /f };
	{ & 'C:\Windows\Setup\Scripts\RemovePackages.ps1' };
	{ & 'C:\Windows\Setup\Scripts\RemoveCapabilities.ps1' };
	{ & 'C:\Windows\Setup\Scripts\RemoveFeatures.ps1' };
	{ net.exe accounts /maxpwage:UNLIMITED };
	{ reg.exe add "HKLM\Software\Policies\Microsoft\Windows\CloudContent" /v "DisableCloudOptimizedContent" /t REG_DWORD /d 1 /f; [System.Diagnostics.EventLog]::CreateEventSource('UnattendGenerator','Application') };
	{ Register-ScheduledTask -TaskName 'UnlockStartLayout' -Xml $(Get-Content -LiteralPath 'C:\Windows\Setup\Scripts\UnlockStartLayout.xml' -Raw) };
	{ reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows Defender Security Center\Notifications" /v DisableNotifications /t REG_DWORD /d 1 /f };
	{ fsutil.exe behavior set disableLastAccess 1 };
	{ reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Dsh" /v AllowNewsAndInterests /t REG_DWORD /d 0 /f };
	{ reg.exe add "HKLM\Software\Policies\Microsoft\Windows\CloudContent" /v "DisableWindowsConsumerFeatures" /t REG_DWORD /d 1 /f };
	{ reg.exe add "HKLM\SYSTEM\CurrentControlSet\Control\BitLocker" /v "PreventDeviceEncryption" /t REG_DWORD /d 1 /f };
	{ reg.exe add "HKLM\Software\Policies\Microsoft\Edge" /v HideFirstRunExperience /t REG_DWORD /d 1 /f };
	{ & 'C:\Windows\Setup\Scripts\SetStartPins.ps1' };
	{ & 'C:\Windows\Setup\Scripts\unattend-01.ps1' };
);

& {
  [float]$complete=0; [float]$increment=100/$scripts.Count;
  foreach($script in $scripts){
    Write-Progress -Id 0 -Activity 'Running scripts to customize Windows. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $($script.ToString().Trim() -replace '\s+',' ' -replace '^(.{99})(.+)$','$1…');
    $start=[datetime]::Now; & $script;
    '*** Finished after {0:0} ms.' -f [datetime]::Now.Subtract($start).TotalMilliseconds;
    "`r`n"*3; $complete+=$increment }
} *>&1 | Out-String -Width 1KB -Stream >> "C:\Windows\Setup\Scripts\Specialize.log";

$scripts = @(
	{ Get-AppxPackage -Name 'Microsoft.Windows.Ai.Copilot.Provider' | Remove-AppxPackage };
	{ [System.Diagnostics.EventLog]::WriteEntry('UnattendGenerator',"User '$env:USERNAME' requested unlock Start menu.",[System.Diagnostics.EventLogEntryType]::Information,1) };
	{ Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Search' -Name 'SearchboxTaskbarMode' -Type 'DWord' -Value 0 };
	{ & 'C:\Windows\Setup\Scripts\SetColorTheme.ps1' };
	{ $r="HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced"; Set-ItemProperty -Path $r -Name "TaskbarMn" -Value 0 -Type DWord -Force };
	{ Get-Process -Name 'explorer' -EA 'SilentlyContinue' | Where-Object { $_.SessionId -eq (Get-Process -Id $PID).SessionId } | Stop-Process -Force };
);
& { [float]$c=0;[float]$inc=100/$scripts.Count; foreach($s in $scripts){Write-Progress -Id 0 -Activity 'Configuring account.' -PercentComplete $c; '*** {0}' -f $($s.ToString().Trim() -replace '\s+',' '); & $s; $c+=$inc }} *>&1 | Out-String -Width 1KB -Stream >> "$env:TEMP\UserOnce.log";

$scripts = @(
	{
		# Per-user trust mirror (IPDROM inherits)
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Internet Settings\ZoneMap\Ranges\IPDROM_PXE" /v ":Range" /t REG_SZ   /d "10.0.6.42" /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Internet Settings\ZoneMap\Ranges\IPDROM_PXE" /v "*"      /t REG_DWORD /d 1 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Policies\Attachments" /v "SaveZoneInformation"      /t REG_DWORD /d 1      /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Policies\Attachments" /v "DefaultFileTypeRisk"      /t REG_DWORD /d 0x6152 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Policies\Attachments" /v "ScanWithAntiVirus"        /t REG_DWORD /d 1      /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Policies\Attachments" /v "HideZoneInfoOnProperties" /t REG_DWORD /d 1      /f;
	};
	{ reg.exe add "HKU\DefaultUser\Software\Policies\Microsoft\Windows\WindowsCopilot" /v TurnOffWindowsCopilot /t REG_DWORD /d 1 /f };
	{ reg.exe add "HKU\DefaultUser\Software\Microsoft\Internet Explorer\LowRegistry\Audio\PolicyConfig\PropertyStore" /f };
	{ Remove-ItemProperty -LiteralPath 'Registry::HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Run' -Name 'OneDriveSetup' -Force -ErrorAction 'Continue' };
	{ reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\GameDVR" /v AppCaptureEnabled /t REG_DWORD /d 0 /f };
	{ reg.exe add "HKU\DefaultUser\Software\Policies\Microsoft\Windows\Explorer" /v "StartLayoutFile" /t REG_SZ /d "C:\Windows\Setup\Scripts\TaskbarLayoutModification.xml" /f; reg.exe add "HKU\DefaultUser\Software\Policies\Microsoft\Windows\Explorer" /v "LockedStartLayout" /t REG_DWORD /d 1 /f };
	{ reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v ShowTaskViewButton /t REG_DWORD /d 0 /f };
	{ reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\DWM" /v ColorPrevalence /t REG_DWORD /d 0 /f };
	{ reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\RunOnce" /v "UnattendedSetup" /t REG_SZ /d "powershell.exe -WindowStyle \""Normal\"" -ExecutionPolicy \""Bypass\"" -NoProfile -File \""C:\Windows\Setup\Scripts\UserOnce.ps1\""" /f };
	{ $r="HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced"; reg.exe add $r /v TaskbarMn /t REG_DWORD /d 0 /f };
);
& { [float]$c=0;[float]$inc=100/$scripts.Count; foreach($s in $scripts){Write-Progress -Id 0 -Activity 'DefaultUser hive.' -PercentComplete $c; '*** {0}' -f $($s.ToString().Trim() -replace '\s+',' '); & $s; $c+=$inc }} *>&1 | Out-String -Width 1KB -Stream >> "C:\Windows\Setup\Scripts\DefaultUser.log";

$scripts = @(
	{ Set-ItemProperty -LiteralPath 'Registry::HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon' -Name 'AutoLogonCount' -Type 'DWord' -Force -Value 0 };
	{ & 'C:\Windows\Setup\Scripts\unattend-02.ps1' };
	{ Remove-Item -LiteralPath @('C:\Windows\Panther\unattend.xml','C:\Windows\Panther\unattend-original.xml','C:\Windows\Setup\Scripts\Wifi.xml') -Force -ErrorAction 'SilentlyContinue' -Verbose };
);
& { [float]$c=0;[float]$inc=100/$scripts.Count; foreach($s in $scripts){Write-Progress -Id 0 -Activity 'Finalize install.' -PercentComplete $c; '*** {0}' -f $($s.ToString().Trim() -replace '\s+',' '); & $s; $c+=$inc }} *>&1 | Out-String -Width 1KB -Stream >> "C:\Windows\Setup\Scripts\FirstLogon.log";
